package cn.sixnine.filmlog;

import android.app.*;
import android.os.Bundle;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.text.*;
import android.view.*;
import android.widget.*;

/** The editor owns only its Bundle until Save; closing never writes an exposure. */
final class PresetEditor {
    private final Activity activity;private final PresetStore store;private final Bundle draft;private final Runnable closed,changed;
    private final java.util.ArrayList<Button> parameterButtons=new java.util.ArrayList<>();
    private Dialog dialog;private AlertDialog confirmation;private LinearLayout body;private ScrollView scroll;
    PresetEditor(Activity activity,LogStore logs,Bundle draft,Runnable closed,Runnable changed){this.activity=activity;store=new PresetStore(logs);this.draft=draft;this.closed=closed;this.changed=changed;}
    private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
    private LinearLayout column(){LinearLayout v=new LinearLayout(activity);v.setOrientation(1);return v;}
    private TextView text(String s,int size){TextView v=new TextView(activity);v.setText(s);v.setTextSize(size);v.setTextColor(UiColors.color(activity.getResources(),0xfff4eee2));v.setPadding(dp(8),dp(8),dp(8),dp(8));return v;}
    private GradientDrawable surface(boolean selected){GradientDrawable v=new GradientDrawable();v.setColor(selected?UiColors.color(activity.getResources(),0xff503326):UiColors.color(activity.getResources(),0xff30251e));v.setCornerRadius(dp(18));v.setStroke(dp(1),selected?UiColors.color(activity.getResources(),0xffef8249):UiColors.color(activity.getResources(),0xff554237));return v;}
    private Button button(String label,Runnable action){Button b=new Button(activity);b.setText(label);b.setStateListAnimator(null);b.setAllCaps(false);b.setTextColor(UiColors.color(activity.getResources(),0xffef8249));b.setTextSize(14);b.setMinHeight(dp(48));b.setMinWidth(0);b.setMinimumWidth(0);b.setBackgroundTintList(null);b.setBackground(surface(false));b.setOnClickListener(v->action.run());return b;}
    private void field(String title,String key,boolean multiline){body.addView(text(title,13));EditText input=new EditText(activity);input.setText(draft.getString(key,""));input.setHint(key.equals("name")?"例如：黄金时刻、影棚…":"备注（例如：暗光曝光）");input.setHintTextColor(UiColors.color(activity.getResources(),0xffb4a99f));input.setTextColor(UiColors.color(activity.getResources(),0xfff4eee2));input.setTextSize(16);input.setSingleLine(!multiline);input.setPadding(dp(12),dp(8),dp(12),dp(8));input.setBackground(surface(false));input.setContentDescription(title);input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){draft.putString(key,s.toString());}public void afterTextChanged(Editable e){}});body.addView(input);}
    private void paintOption(Button b,boolean selected,boolean animate){
        if(b.getTag() instanceof android.animation.ValueAnimator)((android.animation.ValueAnimator)b.getTag()).cancel();int active=PresetStore.iconColor(draft.getString("icon","camera"));int endFill=selected?(0x26000000|(active&0xffffff)):UiColors.color(activity.getResources(),0xff30251e),endInk=selected?active:UiColors.color(activity.getResources(),0xfff4eee2);int startInk=b.getCurrentTextColor(),startFill=b.getBackground() instanceof GradientDrawable&&((GradientDrawable)b.getBackground()).getColor()!=null?((GradientDrawable)b.getBackground()).getColor().getDefaultColor():endFill;boolean before=b.isSelected();b.setSelected(selected);b.setTypeface(android.os.Build.VERSION.SDK_INT>=28?Typeface.create(Typeface.DEFAULT,selected?600:500,false):Typeface.create("sans-serif-medium",0));GradientDrawable shape=new GradientDrawable();shape.setCornerRadius(dp(999));b.setBackground(shape);android.animation.ArgbEvaluator colors=new android.animation.ArgbEvaluator();java.util.function.Consumer<Float> frame=f->{shape.setColor((Integer)colors.evaluate(f,startFill,endFill));b.setTextColor((Integer)colors.evaluate(f,startInk,endInk));shape.setStroke(Math.round(dp(1)*1.5f*((before?1:0)+f*((selected?1:0)-(before?1:0)))),0x80000000|(active&0xffffff));};if(animate){android.animation.ValueAnimator animation=android.animation.ValueAnimator.ofFloat(0,1);animation.setDuration(150);animation.setInterpolator(new android.view.animation.LinearInterpolator());animation.addUpdateListener(v->frame.accept((Float)v.getAnimatedValue()));b.setTag(animation);animation.start();}else frame.accept(1f);
    }
    private void options(String title,String key,String[] values){body.addView(text(title,14));HorizontalScrollView horizontal=new HorizontalScrollView(activity);horizontal.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(activity);for(String value:values){Button b=button(key.equals("aperture")?"f/"+value:value,()->{});parameterButtons.add(b);paintOption(b,value.equals(draft.getString(key,"")),false);b.setOnClickListener(v->{boolean selected=!value.equals(draft.getString(key,""));draft.putString(key,selected?value:"");for(int n=0;n<row.getChildCount();n++){Button other=(Button)row.getChildAt(n);paintOption(other,selected&&other==b,true);}b.performHapticFeedback(HapticFeedbackConstants.CLOCK_TICK);});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(72),dp(48));p.rightMargin=dp(6);row.addView(b,p);}horizontal.addView(row);body.addView(horizontal);}
    void dispose(){if(confirmation!=null)confirmation.dismiss();if(dialog!=null)dialog.dismiss();}
    void show(){
        boolean editing=draft.getBoolean("editing");if(!draft.containsKey("name")){PresetStore.Item item=editing?store.get(draft.getString("id")):new PresetStore.Item();draft.putString("id",item.id);draft.putString("name",item.name);draft.putString("description",item.description);draft.putString("icon",item.icon);draft.putString("aperture",item.aperture);draft.putString("shutter",item.shutter);draft.putString("lens",item.lens);}
        dialog=new Dialog(activity,R.style.FilmDialog);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);dialog.setOnCancelListener(d->closed.run());LinearLayout root=column();root.setPadding(dp(16),dp(12),dp(16),dp(16));root.setBackground(surface(false));LinearLayout header=new LinearLayout(activity);header.setGravity(Gravity.CENTER_VERTICAL);header.addView(text(editing?"编辑模板":"新建模板",21),new LinearLayout.LayoutParams(0,-2,1));Button cancel=button("×",()->{dialog.dismiss();closed.run();});cancel.setContentDescription("取消预设编辑");header.addView(cancel,new LinearLayout.LayoutParams(dp(48),dp(48)));root.addView(header);
        scroll=new ScrollView(activity);body=column();scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));field("模板名称","name",false);field("备注（可选）","description",true);body.addView(text("图标",14));Typeface font=Typeface.createFromAsset(activity.getAssets(),"fonts/Phosphor.ttf");LinearLayout icons=column();for(int line=0;line<2;line++){LinearLayout row=new LinearLayout(activity);for(int col=0;col<5;col++){String key=PresetStore.ICONS[line*5+col];Button b=button(String.valueOf((char)PresetStore.iconCode(key)),()->{});b.setTypeface(font);b.setTextSize(23);b.setTextColor(PresetStore.iconColor(key));b.setContentDescription(key+"图标");b.setSelected(key.equals(draft.getString("icon")));b.setBackground(surface(b.isSelected()));b.setOnClickListener(v->{draft.putString("icon",key);for(Button parameter:parameterButtons)paintOption(parameter,parameter.isSelected(),true);for(int i=0;i<icons.getChildCount();i++){LinearLayout group=(LinearLayout)icons.getChildAt(i);for(int j=0;j<group.getChildCount();j++){Button cell=(Button)group.getChildAt(j);cell.setSelected(cell==b);cell.setBackground(surface(cell==b));}}});row.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));}icons.addView(row);}body.addView(icons);
        options("光圈（可选）","aperture",PresetStore.APERTURES);options("快门（可选）","shutter",PresetStore.SHUTTERS);options("镜头（可选）","lens",PresetStore.LENSES);if(editing)body.addView(text("编辑时留空的备注或参数沿用已有值。",12));
        LinearLayout footer=new LinearLayout(activity);if(editing)footer.addView(button("删除",this::delete),new LinearLayout.LayoutParams(0,dp(48),1));footer.addView(button("保存",()->{try{PresetStore.Item item=new PresetStore.Item();item.id=draft.getString("id");item.name=draft.getString("name","");item.description=draft.getString("description","");item.icon=draft.getString("icon","camera");item.aperture=draft.getString("aperture","");item.shutter=draft.getString("shutter","");item.lens=draft.getString("lens","");store.save(item,editing);Toast.makeText(activity,editing?"模板已更新":"模板已保存",Toast.LENGTH_SHORT).show();root.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);dialog.dismiss();closed.run();changed.run();}catch(Exception error){Toast.makeText(activity,error.getMessage(),Toast.LENGTH_LONG).show();}}),new LinearLayout.LayoutParams(0,dp(48),2));root.addView(footer);dialog.setContentView(root);dialog.show();Window window=dialog.getWindow();if(window!=null){window.setGravity(Gravity.BOTTOM);window.setLayout(-1,dp(Math.min(590,activity.getResources().getConfiguration().screenHeightDp-60)));window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);}scroll.post(()->scroll.scrollTo(0,draft.getInt("scroll")));scroll.setOnScrollChangeListener((v,x,y,ox,oy)->draft.putInt("scroll",y));if(draft.getBoolean("deleting"))delete();
    }
    private void delete(){draft.putBoolean("deleting",true);confirmation=new AlertDialog.Builder(activity).setTitle("删除模板？").setMessage("此模板将被永久删除。").setNegativeButton("取消",(d,w)->draft.putBoolean("deleting",false)).setPositiveButton("删除",(d,w)->{try{store.delete(draft.getString("id"));Toast.makeText(activity,"模板已删除",Toast.LENGTH_SHORT).show();dialog.dismiss();closed.run();changed.run();}catch(Exception error){Toast.makeText(activity,error.getMessage(),1).show();}}).create();confirmation.setOnCancelListener(d->draft.putBoolean("deleting",false));confirmation.show();}
}
